package main

import (
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type EmpRec struct { // 01 EMP-REC, 17 bytes
	ErId    string          // PIC X(5) @0 len=5
	ErDept  string          // PIC X(3) @5 len=3
	ErHours decimal.Decimal // PIC 9(3)V9 @8 len=4
	ErRate  decimal.Decimal // PIC 9(3)V99 @12 len=5
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsFirstFlag string // PIC X len=1 = "Y"
var WsPrevDept string // PIC X(3) len=3 = SPACES
var WsRegHours decimal.Decimal // PIC 9(3)V9 len=4 = 0
var WsOtHours decimal.Decimal // PIC 9(3)V9 len=4 = 0
var WsGross decimal.Decimal // PIC 9(7)V99 len=9 = 0
var WsDeptTotal decimal.Decimal // PIC 9(9)V99 len=11 = 0
var WsDeptCount int64 // PIC 9(3) len=3 = 0
var WsGrandTotal decimal.Decimal // PIC 9(11)V99 len=13 = 0
var WsGrandCount int64 // PIC 9(5) len=5 = 0
var WsHoursEd string // PIC ZZ9.9 len=5
var WsRateEd string // PIC ZZ9.99 len=6
var WsGrossEd string // PIC Z,ZZZ,ZZ9.99 len=12
var WsDeptEd string // PIC ZZZ,ZZZ,ZZ9.99 len=14
var WsGrandEd string // PIC ZZ,ZZZ,ZZZ,ZZ9.99 len=17

var EmpRecData EmpRec
var empLines []string
var empIdx int

func pow10_64(n int) int64 {
	r := int64(1)
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

func fitToPic(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	total := intDigits + int(scale)
	mod := decimal.NewFromInt(1).Shift(int32(total))
	scaled := v.Shift(scale).Truncate(0)
	var r decimal.Decimal
	if scaled.IsNegative() {
		r = scaled.Abs().Mod(mod).Neg()
	} else {
		r = scaled.Mod(mod)
	}
	return r.Shift(-scale)
}

func formatEdited(picture string, v decimal.Decimal) string {
	dot := strings.Index(picture, ".")
	var intPic, fracPic string
	if dot >= 0 {
		intPic = picture[:dot]
		fracPic = picture[dot+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	intSlots := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intSlots++
		}
	}
	fracScale := 0
	for _, c := range fracPic {
		if c == 'Z' || c == '9' {
			fracScale++
		}
	}
	q := v.Truncate(int32(fracScale))
	aq := q.Abs()
	scaled := aq.Shift(int32(fracScale)).Truncate(0)
	total := intSlots + fracScale
	var scaledInt int64
	if total > 0 {
		modDec := decimal.NewFromInt(1).Shift(int32(total))
		scaled = scaled.Mod(modDec)
		scaledInt = scaled.IntPart()
	} else {
		scaledInt = 0
	}
	powF := pow10_64(fracScale)
	var intVal, fracVal int64
	if powF != 0 && fracScale > 0 {
		intVal = scaledInt / powF
		fracVal = scaledInt % powF
	} else {
		intVal = scaledInt
		fracVal = 0
	}
	intDigits := fmt.Sprintf("%0*d", intSlots, intVal)
	var fracDigits string
	if fracScale > 0 {
		fracDigits = fmt.Sprintf("%0*d", fracScale, fracVal)
	}
	firstNonZero := intSlots - 1
	if intSlots > 0 {
		found := false
		for i := 0; i < intSlots; i++ {
			if intDigits[i] != '0' {
				firstNonZero = i
				found = true
				break
			}
		}
		if !found {
			firstNonZero = intSlots - 1
		}
	} else {
		firstNonZero = 0
	}
	var b strings.Builder
	slotIdx := 0
	for _, ch := range intPic {
		if ch == ',' {
			if firstNonZero < slotIdx {
				b.WriteByte(',')
			} else {
				b.WriteByte(' ')
			}
		} else if ch == 'Z' || ch == '9' {
			d := byte('0')
			if slotIdx < len(intDigits) {
				d = intDigits[slotIdx]
			}
			if slotIdx < firstNonZero {
				if ch == 'Z' {
					b.WriteByte(' ')
				} else {
					b.WriteByte(d)
				}
			} else {
				b.WriteByte(d)
			}
			slotIdx++
		} else {
			b.WriteByte(byte(ch))
		}
	}
	res := b.String()
	if dot >= 0 {
		res += "." + fracDigits
	}
	return res
}

func parsePicUnsigned(s string, scale int32) decimal.Decimal {
	var n int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		} else if c == ' ' {
			n = n * 10
		} else {
			n = n * 10
		}
	}
	return decimal.New(n, -scale)
}

func MainPara() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	empLines = nil
	empIdx = 0
	start := 0
	for i := 0; i < len(data); i++ {
		if data[i] == '\n' {
			line := string(data[start:i])
			if len(line) > 0 && line[len(line)-1] == '\r' {
				line = line[:len(line)-1]
			}
			empLines = append(empLines, line)
			start = i + 1
		}
	}
	if start < len(data) {
		line := string(data[start:])
		if len(line) > 0 && line[len(line)-1] == '\r' {
			line = line[:len(line)-1]
		}
		empLines = append(empLines, line)
	}
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	if WsFirstFlag != "Y" {
		DeptBreakPara()
	}
	GrandPara()
}

func ReadPara() {
	if empIdx >= len(empLines) {
		WsEofFlag = "Y"
		return
	}
	line := empLines[empIdx]
	empIdx++
	if len(line) < 17 {
		line += strings.Repeat(" ", 17-len(line))
	} else if len(line) > 17 {
		line = line[:17]
	}
	EmpRecData.ErId = line[0:5]
	EmpRecData.ErDept = line[5:8]
	EmpRecData.ErHours = parsePicUnsigned(line[8:12], 1)
	EmpRecData.ErRate = parsePicUnsigned(line[12:17], 2)
}

func ProcessPara() {
	if WsFirstFlag == "Y" {
		WsPrevDept = EmpRecData.ErDept
		WsFirstFlag = "N"
	} else {
		if EmpRecData.ErDept != WsPrevDept {
			DeptBreakPara()
			WsPrevDept = EmpRecData.ErDept
		}
	}
	PayPara()
	ReadPara()
}

func PayPara() {
	if EmpRecData.ErHours.GreaterThan(decimal.NewFromInt(40)) {
		WsRegHours = fitToPic(decimal.NewFromInt(40), 3, 1)
		t := EmpRecData.ErHours.Sub(decimal.NewFromInt(40)).Truncate(1)
		WsOtHours = fitToPic(t, 3, 1)
	} else {
		WsRegHours = fitToPic(EmpRecData.ErHours.Truncate(1), 3, 1)
		WsOtHours = fitToPic(decimal.NewFromInt(0), 3, 1)
	}
	oneHalf := decimal.New(15, -1)
	expr := WsRegHours.Mul(EmpRecData.ErRate).Add(WsOtHours.Mul(EmpRecData.ErRate).Mul(oneHalf))
	WsGross = fitToPic(expr.Round(2), 7, 2)
	WsDeptTotal = fitToPic(WsDeptTotal.Add(WsGross).Truncate(2), 9, 2)
	WsDeptCount = (WsDeptCount + 1) % 1000
	WsGrandTotal = fitToPic(WsGrandTotal.Add(WsGross).Truncate(2), 11, 2)
	WsGrandCount = (WsGrandCount + 1) % 100000
	WsHoursEd = formatEdited("ZZ9.9", EmpRecData.ErHours)
	WsRateEd = formatEdited("ZZ9.99", EmpRecData.ErRate)
	WsGrossEd = formatEdited("Z,ZZZ,ZZ9.99", WsGross)
	line := EmpRecData.ErId + " " + EmpRecData.ErDept + " " + WsHoursEd + " " + WsRateEd + " " + WsGrossEd
	fmt.Fprintln(os.Stdout, line)
}

func DeptBreakPara() {
	WsDeptEd = formatEdited("ZZZ,ZZZ,ZZ9.99", WsDeptTotal)
	line := "  DEPT " + WsPrevDept + " EMPLOYEES: " + fmt.Sprintf("%03d", WsDeptCount) + " TOTAL: " + WsDeptEd
	fmt.Fprintln(os.Stdout, line)
	WsDeptTotal = decimal.NewFromInt(0)
	WsDeptCount = 0
}

func GrandPara() {
	WsGrandEd = formatEdited("ZZ,ZZZ,ZZZ,ZZ9.99", WsGrandTotal)
	line := "GRAND TOTAL (" + fmt.Sprintf("%05d", WsGrandCount) + "): " + WsGrandEd
	fmt.Fprintln(os.Stdout, line)
}

func init() {
	WsEofFlag = "N"
	WsFirstFlag = "Y"
	WsPrevDept = "   "
}

func main() {
	MainPara()
}
